from pathlib import Path
p=Path('lobbying-map/app/page.tsx');s=p.read_text()
s=s.replace('periodLabel,readable,readData','periodLabel,readable,readData,researchLabel')
s=s.replace('type Index={companies:', 'type Index={research:{total:number;counts:Record<string,number>;updated:string};companies:')
s=s.replace("const [data,setData]", "const [kind,setKind]=useState('all'),[ownership,setOwnership]=useState('all'),[research,setResearch]=useState('all'),[featured,setFeatured]=useState(false);\n const [data,setData]")
s=s.replace('/data/directory-v2.json.gz','/data/directory-v3.json.gz')
s=s.replace('[q,year,sort,selected,detailYear,includeInactive]', '[q,year,sort,selected,detailYear,includeInactive,kind,ownership,research,featured]')
s=s.replace("(year==='all'||c.years[year])&&(c.name", "(year==='all'||c.years[year])&&(kind==='all'||(c.profile?.kind||'Unknown')===kind)&&(ownership==='all'||(c.profile?.ownership||'Unknown')===ownership)&&(research==='all'||(c.profile?.status||'pending')===research)&&(!featured||c.profile?.featured)&&(c.name")
s=s.replace('[data,q,year,sort]);','[data,q,year,sort,kind,ownership,research,featured]);')
s=s.replace("setYear('all')}}", "setYear('all');setKind('all');setOwnership('all');setResearch('all');setFeatured(false)}}")
s=s.replace('<h1>Companies & organizations</h1>', '''<h1>Companies & organizations</h1><p>Who they are, what they do, and their federal lobbying disclosures.</p>{data&&<p className="research-progress">Research in progress: <strong>{fmt(data.research.counts.sourced||0)} sourced profiles</strong> · {fmt(data.research.counts.self_reported||0)} self-reported descriptions · {fmt(data.research.counts.unresolved||0)} unresolved identities · {fmt(data.research.counts.pending||0)} awaiting research.<br/><span className="secondary">Ownership describes the date shown in each profile, independently of the activity-year filter.</span></p>}''')
s=s.replace('onChange={setSort}/></div><p className="count"', '''onChange={setSort}/></div><details className="refine"><summary>Filter by organization type, ownership or research status</summary><div className="controls"><Choice label="Organization type" value={kind} options={ [['all','All types'],...['Business','Business / nonprofit group','Nonprofit / initiative','Trade / business association','Government','Unknown'].map(v=>[v,v] as [string,string])] } onChange={setKind}/><Choice label="Ownership" value={ownership} options={ [['all','All ownership'],...['Publicly traded','Privately held','Subsidiary of public company','Nonprofit-controlled business','Government body','Not applicable','Unknown'].map(v=>[v,v] as [string,string])] } onChange={setOwnership}/><Choice label="Research status" value={research} options={ [['all','All research stages'],['sourced','Sourced profile'],['self_reported','Self-reported only'],['unresolved','Identity unresolved'],['pending','Not researched yet']] } onChange={setResearch}/></div></details><label className="toggle"><input type="checkbox" checked={featured} onChange={e=>setFeatured(e.target.checked)}/> Show well-known organizations only <span className="secondary">Curated selection, not a popularity ranking</span></label>{!q&&!featured&&kind==='all'&&ownership==='all'&&research==='all'&&<div className="featured-links" aria-label="Explore well-known organizations">{data?.companies.filter(c=>c.profile?.featured&&(year==='all'||c.years[year])).slice(0,12).map(c=><button key={c.id} onClick={()=>setSelected(c.id)}>{c.name}</button>)}</div>}<p className="count"''')
s=s.replace('{c.name}</button>{c.aliases.length', '''{c.name}</button>{c.profile?.featured&&<span className="badge">Well-known</span>}<span className="description">{c.profile?.description||'This organization has not been researched yet.'}</span><span className="secondary">{researchLabel(c.profile?.status)}{c.profile&&c.profile.kind!=='Unknown'?' · '+c.profile.kind:''}{c.profile&&c.profile.ownership!=='Unknown'&&c.profile.ownership!=='Not applicable'?' · '+c.profile.ownership:''}</span>{c.aliases.length''')
s=s.replace('<h1>{company.name}</h1><details', '''<h1>{company.name}</h1><section className="profile" aria-label="Organization profile">{company.profile?<><p className="profile-description">{company.profile.description}</p><p className="secondary">{researchLabel(company.profile.status)} · Checked {company.profile.checked_at}{company.profile.as_of?' · Information as of '+company.profile.as_of:''}</p><dl><div><dt>Organization type</dt><dd>{company.profile.kind==='Unknown'?'Not established':company.profile.kind}</dd></div><div><dt>Ownership</dt><dd>{company.profile.ownership==='Unknown'?'Not established':company.profile.ownership}</dd></div>{company.profile.legal_form&&<div><dt>Legal form</dt><dd>{company.profile.legal_form}</dd></div>}{company.profile.website&&<div><dt>Website</dt><dd><a href={company.profile.website} target="_blank" rel="noreferrer">{new URL(company.profile.website).hostname} ↗</a></dd></div>}</dl><p>{company.profile.notes}</p><details><summary>Profile sources ({company.profile.sources.length})</summary><ul>{company.profile.sources.map(source=><li key={source.url}><a href={source.url} target="_blank" rel="noreferrer">{source.label} ↗</a><span className="secondary">{source.claim}</span></li>)}</ul></details>{!!company.profile.other_descriptions?.length&&<details><summary>Other self-reported descriptions ({company.profile.other_descriptions.length})</summary><ul>{company.profile.other_descriptions.map((r,i)=><li key={i}>{r.description} <a href={r.url} target="_blank" rel="noreferrer">LDA source · {r.effective_date}</a></li>)}</ul></details>}</>:<p>Not researched yet. The original filings below are available; this organization’s identity, business and ownership have not been established.</p>}</section><details''')
s=s.replace('<p>Capitalization, punctuation', '<p>Annotations are being researched one entry at a time. Sourced profiles cite evidence for their claims; missing facts remain unknown. Self-reported descriptions are supplied by LDA filers and matched by exact disclosed name, which does not independently establish identity. “Well-known” is an editorial selection, not a measured ranking or an endorsement. Ownership is dated separately from lobbying activity and may have changed.</p><p>Capitalization, punctuation')
p.write_text(s)
